#!/usr/bin/env node
// RC2.9.4-B9. Single-band acceptance through the PRODUCT path.
//
// For EASY and for MEDIUM: N independent journeys of S sittings × C questions,
// each sitting generated by the shipped page (index.html + app.js +
// practice-journey.js) in a real browser, the journey carried by the product's
// own storage between sittings, and every rolling hundred measured with the
// RC2.9.2 perceptual classifier. Presets are exercised the same way: one
// sitting per preset per band, so «the preset delivers» is a product fact.
//
// Usage: node tools/audit/rc294-single-band-acceptance.mjs [journeys] [sittings] [count] [out]

import {writeFileSync} from 'node:fs';
import {serveRepository, launchBrowser, playProductJourney, browserAvailable} from './rc291-product-journey.mjs';
import {measureSample, classify} from '../../src/qa/perceptual-classify.js';

const [J = '6', S = '4', C = '30', OUT = 'rc2/RC294_SINGLE_BAND_ACCEPTANCE.txt'] = process.argv.slice(2);
const GATE = {flagged: 8, nd: 5, cluster: 3, run: 2, dup: 0};

function windows(questions) {
  const out = [];
  for (let start = 0; start + 100 <= questions.length; start += 10) {
    const rows = questions.slice(start, start + 100);
    const m = measureSample(rows, {label: `Q${start + 1}-${start + 100}`});
    out.push({label: `Q${start + 1}–${start + 100}`, pv: m.counts.PARAMETER_ONLY_VARIANT, nd: m.counts.NEAR_DUPLICATE_CONSTRUCTION,
      flagged: m.flagged, cluster: m.largestPerceptualCluster, run: m.longestSimilarRun,
      dup: rows.length - new Set(rows.map(q => q.metadata.normalized_stem_identity)).size});
  }
  return out;
}

/** The flagged pairs of a window, rendered, so a human can judge them. */
function flaggedPairs(questions, limit = 6) {
  const rows = classify(questions);
  const seen = new Map();
  const pairs = [];
  for (const r of rows) {
    if (r.label === 'NEAR_DUPLICATE_CONSTRUCTION' && pairs.length < limit) {
      const first = seen.get(r.perceptual);
      pairs.push({kind: 'ND', a: first, b: r});
    }
    if (!seen.has(r.perceptual)) seen.set(r.perceptual, r);
  }
  return pairs;
}

if (!(await browserAvailable())) {
  console.log('no browser available; this acceptance needs Chromium and playwright-core');
  process.exit(2);
}
const {server, origin} = await serveRepository();
const browser = await launchBrowser();
const lines = [];
const log = s => { lines.push(s); console.log(s); };
log(`RC2.9.4-B9 single-band acceptance — product path (browser), ${J} journeys × ${S} sittings × ${C} per band`);
log(`gates per rolling 100: PV+ND ≤ ${GATE.flagged}, ND ≤ ${GATE.nd}, cluster ≤ ${GATE.cluster}, streak ≤ ${GATE.run}, duplicate stems = ${GATE.dup}`);
const summary = {};
try {
  for (const band of ['easy', 'medium']) {
    log(`\n=== ${band.toUpperCase()} journeys ===`);
    log('journey            questions refusals | worst window: PV  ND PV+ND cluster run dup | windows breaching PV+ND≤8');
    const bandRows = [];
    for (let j = 1; j <= Number(J); j++) {
      const seeds = Array.from({length: Number(S)}, (_, s) => `rc294-b9-${band}-j${j}-s${s + 1}`);
      // A fresh browser context per journey: a fresh user.
      const r = await playProductJourney(browser, origin, {seeds, count: Number(C), difficulty: band});
      const questions = r.sessions.flatMap(s => s.questions);
      const refusals = r.sessions.filter(s => s.refusal).length;
      const w = windows(questions);
      const worst = w.reduce((a, x) => ({pv: Math.max(a.pv, x.pv), nd: Math.max(a.nd, x.nd), flagged: Math.max(a.flagged, x.flagged), cluster: Math.max(a.cluster, x.cluster), run: Math.max(a.run, x.run), dup: Math.max(a.dup, x.dup)}), {pv: 0, nd: 0, flagged: 0, cluster: 0, run: 0, dup: 0});
      const breaching = w.filter(x => x.flagged > GATE.flagged).length;
      bandRows.push({j, questions: questions.length, refusals, worst, windows: w.length, breaching, calls: r.calls});
      log(`${band}-j${j}`.padEnd(19) + `${String(questions.length).padStart(4)} ${String(refusals).padStart(3)}      | ${String(worst.pv).padStart(3)} ${String(worst.nd).padStart(3)} ${String(worst.flagged).padStart(5)} ${String(worst.cluster).padStart(6)} ${String(worst.run).padStart(4)} ${String(worst.dup).padStart(3)} | ${breaching}/${w.length}`);
      if (j === 1) {
        const pairs = flaggedPairs(questions.slice(0, 100));
        if (pairs.length) { log(`  flagged pairs in Q1–100 of ${band}-j1 (for human inspection):`); for (const p of pairs) log(`   [${p.kind}] ${p.a.templateId} #${p.a.index}: ${p.a.question.slice(0, 90)}\n        ~ ${p.b.templateId} #${p.b.index}: ${p.b.question.slice(0, 90)}`); }
      }
    }
    summary[band] = bandRows;
    log(`\n--- ${band.toUpperCase()} presets through the product (one fresh journey per preset, 2 sittings) ---`);
    for (const count of [5, 10, 14, 20, 30]) {
      const r = await playProductJourney(browser, origin, {seeds: [`rc294-b9-${band}-p${count}-s1`, `rc294-b9-${band}-p${count}-s2`], count, difficulty: band});
      const delivered = r.sessions.map(s => s.questions.length);
      log(`preset ${String(count).padStart(2)}: delivered ${delivered.join(' + ')}${r.sessions.some(s => s.refusal) ? '  REFUSED: ' + r.sessions.map(s => s.refusal).filter(Boolean).join(' | ') : ''}`);
    }
    log(`--- ${band.toUpperCase()} custom 40 / 50 through the product ---`);
    for (const count of [40, 50]) {
      const r = await playProductJourney(browser, origin, {seeds: [`rc294-b9-${band}-c${count}-s1`], count, difficulty: band});
      log(`custom ${count}: delivered ${r.sessions[0].questions.length}${r.sessions[0].refusal ? '  REFUSED: ' + r.sessions[0].refusal : ''}`);
    }
  }
} finally {
  await browser.close();
  server.close();
}
writeFileSync(OUT, lines.join('\n') + '\n');
console.log(`\nwrote ${OUT}`);
